UPDATE project
SET owner_id = #{ownerId}
WHERE project_id = #{projectId}

mapper.select:
SELECT COUNT(*) FROM project p LEFT JOIN member m ON p.owner_id = m.member_id LEFT JOIN univ_department ud ON m.dept_id = ud.dept_id
AND p.match_scope = '교내'
AND ud.univ_name = #{userUnivName}
AND p.match_scope = '전국'
AND p.status = #{tab}
AND ( p.title LIKE CONCAT('%', #{keyword}, '%') OR p.summary LIKE CONCAT('%', #{keyword}, '%') OR p.tags LIKE CONCAT('%', #{keyword}, '%') )
AND p.category IN
#{category}
AND (p.category != '학과' OR m.dept_id = #{userDeptId})
AND ( p.target_grade = '무관' OR p.target_grade = 'ALL' OR p.target_grade = 'all' OR p.target_grade IS NULL OR p.target_grade = ''
OR p.target_grade LIKE CONCAT('%', #{grade}, '%')
)

mapper.update:
update project
set favorite_count = favorite_count +1
where project_id = #{projectId}

update project
set favorite_count = favorite_count -1
where project_id = #{projectId}

mapper.select:
select count(*)
from favorite
where member_id = #{memberId} and project_id = #{projectId}

SELECT COUNT(*) 
FROM favorite f 
WHERE f.member_id = #{memberId}

SELECT p.* 
FROM project p 
INNER JOIN favorite f ON p.project_id = f.project_id 
WHERE f.member_id = #{memberId} 
ORDER BY f.project_id DESC 
LIMIT #{amount} OFFSET #{offset}

